def is_costas(p):
    n = len(p)
    diffs = set()
    for i in range(n):
        for j in range(i + 1, n):
            diff = (j - i, p[j] - p[i])
            if diff in diffs:
                return False
            diffs.add(diff)
    return True

def solve_costas(n):
    import itertools
    for p in itertools.permutations(range(n)):
        if is_costas(p):
            return p
    return None

# Let's try to find one.
# Wait, 10! is 3,628,800. This should be fast enough.
print(solve_costas(10))
